DROP TABLE IF EXISTS `dev_phase_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dev_phase_template` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(50) NOT NULL COMMENT '阶段名称',
  `default_days` int DEFAULT '0' COMMENT '默认天数',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `product_status_sync` tinyint(1) DEFAULT '0' COMMENT '是否触发产品状态同步(研发中→正常)',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_name_company` (`name`,`company_id`),
  UNIQUE KEY `uk_company_name` (`company_id`,`name`),
  KEY `idx_sort` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=88 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='研发项目阶段模板表';
/*!40101 SET character_set_client = @saved_cs_client */;

