/*!40000 ALTER TABLE `dev_phase_template` DISABLE KEYS */;
INSERT INTO `dev_phase_template` VALUES (74,'立项',0,1,0,'',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(75,'结构评估',2,2,0,'根据玻璃尺寸和摄像头孔位与R角来综合评估结构是否支持立项。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(76,'立项准备',5,3,0,'根据项目型号收手机，拆分成机板和屏幕分体状态，交给触摸方案公司抓取触摸协议，明确是否可以破解协议以及用哪颗物料可以满足技术标准。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(77,'显示评估',2,4,0,'提供机板和原屏给到显示方案公司，并告知触摸方案商建议使用的触摸IC料号及规格书与触摸原理图，让显示方案公司抓取显示协议，根据手机的分辨率与刷新率和玻璃的分辨率综合评估用哪颗码片物料，以及驱动IC。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(78,'排线图纸',3,5,0,'根据触摸方案公司建议的触摸IC和显示方案公司建议的码片，开始画图纸，一般都可以画，后期一般是谁画的图纸就和谁买码片。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(79,'排线打样',4,6,0,'出图纸后，把图纸给到排线工厂打样，一般打10PCS，码片和触摸IC需要找方案公司提供，哪个公司画的排线图纸就找哪个公司寄码片，触摸公司寄触摸IC。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(80,'FOG打样',2,7,0,'排线打样好之后直接让工厂寄给打样加工厂，同时需要寄驱动IC过去和玻璃过去，一般先打样5PCS。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(81,'显示调试',5,8,0,'FOG打样直接寄到显示方案公司，并且提供机板，开始调试显示功能。其他兼容的基板，等没什么大问题再去购买给方案公司做兼容。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(82,'触摸调试',5,9,0,'初版显示做好以后，移交机板和FOG去触摸方案公司调试触摸。同时保留一个机板和FOG去盖板厂根据屏幕的实际显示效果开模做盖板样品，然后去背贴厂开背贴样品。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(83,'背贴盖板打样',2,10,0,'使用保留的一个机板和FOG去盖板厂根据屏幕的实际显示效果开模做盖板样品，然后去背贴厂开背贴样品。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(84,'总成样品',2,11,0,'将盖板和背贴样品寄到加工厂做成总成，需要寄2PCS总成和机板过去方案公司优化触摸。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(85,'测试',5,12,0,'开始测试，需要测试结构/显示/触摸，详见测试文档。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(86,'小批量',3,13,0,'测试没问题之后，下物料寄到工厂，先进行100PCS的小批量，到货后过一遍，没有批次问题，就可以结项了。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31'),(87,'结项',0,14,0,'结项，通知工厂开始量产。',1,'2026-09-18 01:58:31','2026-09-18 01:58:31');
/*!40000 ALTER TABLE `dev_phase_template` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `dev_project_phase`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `dev_project_phase` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `phase_name` varchar(50) NOT NULL COMMENT '节点名称',
  `sort_order` int DEFAULT '0' COMMENT '排序',
  `default_days` int DEFAULT '0' COMMENT '默认天数',
  `planned_end` date DEFAULT NULL COMMENT '计划完成日期',
  `actual_end` date DEFAULT NULL COMMENT '实际完成日期',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  `status` varchar(20) DEFAULT NULL COMMENT '状态',
  `company_id` bigint DEFAULT NULL COMMENT '公司ID',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_project_id` (`project_id`),
  KEY `idx_company_id` (`company_id`)
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='项目阶段表';
/*!40101 SET character_set_client = @saved_cs_client */;

